//! 自作乗数からのbox最小点をRepairへ渡す独立主解診断。
use mip_codex::{mps,heuristic::Repair,solve::Result};
use std::{fs::File,time::{Instant,Duration}};
fn main(){let a:Vec<_>=std::env::args().collect();if a.get(1).is_some_and(|v|v=="build-info"){println!("{}",serde_json::json!({"source_directory":env!("CARGO_MANIFEST_DIR"),"source_fingerprint":mip_codex::BUILD_SOURCE_FINGERPRINT,"library_source_directory":mip_codex::BUILD_SOURCE_DIRECTORY,"library_source_fingerprint":mip_codex::BUILD_SOURCE_FINGERPRINT}));return;}let m=mps::read(&a[1]).unwrap();let input:serde_json::Value=serde_json::from_reader(File::open(&a[2]).unwrap()).unwrap();assert!(!m.maximize&&m.variables.iter().all(|v|v.integer&&v.lower==Some(0.)&&v.upper==Some(1.)));let mut x:Vec<_>=m.variables.iter().map(|v|input["values"][&v.name].as_f64().unwrap()).collect();let mut repair=Repair::new(&m);assert!(repair.candidate_check(&x));let mut reduced:Vec<_>=m.variables.iter().map(|v|v.objective).collect();for entry in input["row_subgradient_proof"]["multipliers"].as_array().unwrap(){let i=entry[0].as_u64().unwrap()as usize;let y=f64::from_bits(u64::from_str_radix(entry[1].as_str().unwrap(),16).unwrap());assert!(y.is_finite()&&y>=0.);for &(j,c)in &m.rows[i].coefficients{reduced[j]-=y*c;}}let costs:Vec<_>=m.variables.iter().map(|v|v.objective).filter(|&v|v>0.).collect();let mut costs=costs;costs.sort_by(f64::total_cmp);let scale=costs[costs.len()/2];let lo:Vec<_>=m.variables.iter().map(|v|v.lower).collect();let hi:Vec<_>=m.variables.iter().map(|v|v.upper).collect();let began=Instant::now();let seconds:f64=a[3].parse().unwrap();let end=began+Duration::from_secs_f64(seconds);let mut improvements=0;let modes=if a[5]=="portfolio"{vec!["zero","dual"]}else{vec![a[5].as_str()]};for mode in modes{let initial:Vec<_>=reduced.iter().enumerate().map(|(j,&c)|if mode=="zero"{0.001}else if c<0.{0.95}else if c>0.{0.001}else{if x[j]>0.5{0.95}else{0.001}}).collect();for seed in 0..16{if Instant::now()>=end||repair.stats.work>=100_000_000{break;}if let Some(v)=repair.search_priced(&initial,&lo,&hi,end,100_000_000usize.saturating_sub(repair.stats.work),seed,1.,scale){let objective=m.objective(&v);if repair.candidate_check(&v)&&objective.is_finite()&&objective<m.objective(&x)-4e-8*(1.+objective.abs().max(m.objective(&x).abs())){x=v;improvements+=1;}}}}let r=Result{status:"feasible_dual_guided_repair_diagnostic".into(),objective:Some(m.objective(&x)),values:Some(m.variables.iter().zip(x).map(|(v,x)|(v.name.clone(),x)).collect()),seconds:began.elapsed().as_secs_f64(),..Result::default()};serde_json::to_writer(File::create(&a[4]).unwrap(),&r).unwrap();println!("{}",serde_json::json!({"objective":r.objective,"seconds":r.seconds,"calls":repair.stats.calls,"moves":repair.stats.moves,"work":repair.stats.work,"improvements":improvements}));}
